You are assigned to issue #597: 'Add reproducible Infigraph runtime and capability contract'.

## Context
The project lacks an integration layer to reproducibly invoke the Infigraph CLI. As a result, there is no way to perform analysis using Infigraph while guaranteeing that the environment has the correct, pinned version and the required capabilities.

## Implementation Plan

Create a new wrapper module `scripts/kb/infigraph.py` to handle the reproducible Infigraph runtime, and a corresponding test file `tests/kb/test_infigraph.py`.

Here is a concrete example of the implementation for `scripts/kb/infigraph.py`:

```python
import enum
import json
import subprocess
from dataclasses import dataclass
from typing import Optional, Dict, Any

# Reproducible resolution metadata
INFIGRAPH_VERSION_PIN = "1.0.0"
INFIGRAPH_EXPECTED_CAPABILITIES = {"graph_analysis", "syntax_tree"}

class InfigraphStatus(enum.Enum):
    ANALYSIS_COMPLETE = "analysis_complete"
    ANALYSIS_UNAVAILABLE = "analysis_unavailable"
    ANALYSIS_FAILED = "analysis_failed"

@dataclass
class InfigraphResult:
    status: InfigraphStatus
    reason: Optional[str] = None
    data: Optional[Dict[str, Any]] = None

class InfigraphWrapper:
    def __init__(self, executable_path: str = "infigraph", timeout: int = 30):
        self.executable_path = executable_path
        self.timeout = timeout

    def check_capabilities(self) -> InfigraphResult:
        try:
            result = subprocess.run(
                [self.executable_path, "--capabilities"],
                capture_output=True,
                text=True,
                timeout=self.timeout
            )
            if result.returncode != 0:
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_UNAVAILABLE,
                    reason=f"Executable misconfigured or unsupported. Return code {result.returncode}"
                )

            try:
                capabilities = json.loads(result.stdout)
            except json.JSONDecodeError:
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_UNAVAILABLE,
                    reason="Malformed output from capabilities check"
                )

            provided = set(capabilities.get("capabilities", []))
            if not INFIGRAPH_EXPECTED_CAPABILITIES.issubset(provided):
                missing = INFIGRAPH_EXPECTED_CAPABILITIES - provided
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_UNAVAILABLE,
                    reason=f"Missing required capabilities: {missing}"
                )

            version = capabilities.get("version")
            if version != INFIGRAPH_VERSION_PIN:
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_UNAVAILABLE,
                    reason=f"Version mismatch. Expected {INFIGRAPH_VERSION_PIN}, got {version}"
                )

            return InfigraphResult(status=InfigraphStatus.ANALYSIS_COMPLETE)

        except FileNotFoundError:
            return InfigraphResult(
                status=InfigraphStatus.ANALYSIS_UNAVAILABLE,
                reason="Executable unavailable"
            )
        except subprocess.TimeoutExpired:
            return InfigraphResult(
                status=InfigraphStatus.ANALYSIS_FAILED,
                reason="Capabilities check timed out"
            )

    def run_analysis(self, target_path: str) -> InfigraphResult:
        capabilities_check = self.check_capabilities()
        if capabilities_check.status != InfigraphStatus.ANALYSIS_COMPLETE:
            return capabilities_check

        try:
            result = subprocess.run(
                [self.executable_path, "analyze", target_path],
                capture_output=True,
                text=True,
                timeout=self.timeout
            )
            if result.returncode != 0:
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_FAILED,
                    reason=f"Analysis command failed. Return code {result.returncode}: {result.stderr.strip()}"
                )

            try:
                data = json.loads(result.stdout)
                return InfigraphResult(status=InfigraphStatus.ANALYSIS_COMPLETE, data=data)
            except json.JSONDecodeError:
                return InfigraphResult(
                    status=InfigraphStatus.ANALYSIS_FAILED,
                    reason="Malformed output from analysis command"
                )

        except subprocess.TimeoutExpired:
            return InfigraphResult(
                status=InfigraphStatus.ANALYSIS_FAILED,
                reason="Analysis command timed out"
            )
```

## Acceptance Criteria
- The selected Infigraph release and resolution metadata are recorded reproducibly and can be verified in CI.
- Startup checks distinguish an executable that is unavailable, unsupported, or misconfigured from one that is ready to analyze.
- The wrapper defines normalized statuses for `analysis_complete`, `analysis_unavailable`, and `analysis_failed`, including actionable failure reasons.
- Tests use a fake executable to cover successful capability discovery and representative installation, capability, command, timeout, and malformed-output failures.
- No cross-repository graph storage or MCP integration is introduced.

## Boundary Rules
You may ONLY modify the files listed above (`scripts/kb/infigraph.py`, `tests/kb/test_infigraph.py`). If a test file outside your boundary fails, you must make your source changes backward-compatible so the existing test passes unmodified. Do NOT rename, move, or delete any files outside your boundary.
